// @vitest-environment jsdom
import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, expect, test } from 'vitest';

import { App } from '/home/sandbox/workspace/src/App';

beforeEach(() => {
  localStorage.clear();
  document.body.className = '';
});
afterEach(cleanup);

test('defaults to light and persists a switch to dark', () => {
  render(<App />);
  expect(screen.getByTestId('current-theme').textContent).toBe('light');
  expect(document.body.classList.contains('g-root_theme_light')).toBe(true);

  fireEvent.click(screen.getByLabelText('Dark'));

  expect(localStorage.getItem('theme')).toBe('dark');
  expect(screen.getByTestId('current-theme').textContent).toBe('dark');
  expect(document.body.classList.contains('g-root_theme_dark')).toBe(true);
  expect(document.body.classList.contains('g-root_theme_light')).toBe(false);
});

test('restores the stored theme on a fresh mount (simulated reload)', () => {
  localStorage.setItem('theme', 'dark');
  render(<App />);
  expect(screen.getByTestId('current-theme').textContent).toBe('dark');
  expect(document.body.classList.contains('g-root_theme_dark')).toBe(true);
  expect((screen.getByLabelText('Dark') as HTMLInputElement).checked).toBe(true);
});

test('ignores garbage in storage and falls back to light', () => {
  localStorage.setItem('theme', 'purple');
  render(<App />);
  expect(screen.getByTestId('current-theme').textContent).toBe('light');
});

test('follows a change made in another tab via the storage event', () => {
  render(<App />);
  localStorage.setItem('theme', 'dark');
  fireEvent(window, new StorageEvent('storage', { key: 'theme', newValue: 'dark' }));
  expect(screen.getByTestId('current-theme').textContent).toBe('dark');
});
EOF
